from decimal import Decimal
from urllib.parse import quote
from acquire_sources import BASE,OUT,receipts,savejson
def pct(a,b):return f'{Decimal(a)*100/Decimal(b):.8f}'
def url(key):return next(r for r in receipts if r['id']==key)['url'].replace(' ','%20')
def citation(key,label):return f'[{label}]({url(key)})'
def main():
    rows=list(csv.DictReader((BASE/'data/county-turnout.csv').open()));contract=json.loads((OUT/'priority-set.json').read_text());participation=list(csv.DictReader((OUT/'participation-controls.csv').open()));active=list(csv.DictReader((OUT/'active-registration.csv').open()));prior={x['fips'] for x in rows if x['priority']=='True'}
    scenarios=[]
    historical_path=OUT/'historical-county-candidate-votes.csv';historical=list(csv.DictReader(historical_path.open())) if historical_path.exists() else [];histvectors=[]
    for date in sorted({r['election_date'] for r in historical}):
        selected=[r for r in historical if r['election_date']==date];v={}
        for r in selected:v[r['fips']]=v.get(r['fips'],0)+int(r['votes'])
        if len(v)==82:histvectors.append((('2018 November6 same-seat special election' if date=='2018-11-06' else '2018 November27 same-seat special runoff')+' named candidates','contest_votes',v))
    for name,kind,v in [
      ('2024 Senate certified named candidates','contest_votes',{x['fips']:int(x['2024_senate_candidate_votes']) for x in rows}),
      ('2024 president certified named candidates','contest_votes',{x['fips']:int(x['2024_president_candidate_votes']) for x in rows}),
      ('2020 Senate amended named candidates','contest_votes',{x['fips']:int(x['2020_senate_candidate_votes']) for x in rows}),
      ('2022 EAC v1.1 F1a counted-ballot participation','survey_participation',{x['fips']:int(x['value']) for x in participation if x['year']=='2022' and x['field']=='F1a'}),
      ('2024 EAC v2 F1a counted-ballot participation','survey_participation',{x['fips']:int(x['value']) for x in participation if x['year']=='2024' and x['field']=='F1a'}),
    ]+histvectors+[(key,'monthly_active_registration',{x['fips']:int(x['active_voters']) for x in active if x['source_id']==key}) for key in sorted({x['source_id'] for x in active})]:
        assert len(v)==82;ordered=sorted(rows,key=lambda r:(-v[r['fips']],r['fips']));total=sum(v.values());cum=0;cross=None;order=[]
        for i,r in enumerate(ordered,1):
            before=cum;cum+=v[r['fips']];order.append(dict(rank=i,fips=r['fips'],county=r['county'],value=v[r['fips']],cumulative=cum))
            if cross is None and 5*cum>=4*total:cross=dict(count=i,votes=cum,preceding_votes=before,crossing_county=r['county'])
        scenarios.append(dict(label=name,measure=kind,state_total=total,top15_votes=sum(v[r['fips']] for r in ordered[:15]),priority41_votes=sum(v[k] for k in prior),minimum80=cross,all_county_order=order))
    savejson(OUT/'volume-sensitivity.json',scenarios)
    with (OUT/'volume-sensitivity-order.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['label','measure','state_total','rank','fips','county','value','cumulative']);w.writeheader()
        for s in scenarios:w.writerows(dict(label=s['label'],measure=s['measure'],state_total=s['state_total'],**r) for r in s['all_county_order'])
    names=', '.join(x['county'] for x in rows[:15]);minnames=', '.join(x['county'] for x in rows[:41]);remainder=', '.join(x['county'] for x in rows[41:])
